import{_ as t}from"./chunks/my-system.CS4oEI92.js";import{_ as a,o as s,c as o,ag as i}from"./chunks/framework.DqVSm8kp.js";const h=JSON.parse('{"title":"Mon Système","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/system.md","filePath":"fr/guide/system.md"}'),r={name:"fr/guide/system.md"};function n(l,e,d,c,u,m){return s(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="mon-systeme" tabindex="-1">Mon Système <a class="header-anchor" href="#mon-systeme" aria-label="Permalink to &quot;Mon Système&quot;">​</a></h1><p>La page Système affiche les spécifications matérielles réelles et le statut d&#39;Ollama en direct -- des données provenant de votre OS, pas des estimations du navigateur.</p><p><strong>Élément de la barre latérale :</strong> Mon Système <strong>Route :</strong> <code>/system</code></p><p><img src="'+t+'" alt="Interface Mon Système"></p><h2 id="detection-du-materiel" tabindex="-1">Détection du matériel <a class="header-anchor" href="#detection-du-materiel" aria-label="Permalink to &quot;Détection du matériel&quot;">​</a></h2><p>LLMxRay utilise un plugin Vite personnalisé (<code>vite-plugin-system-info</code>) qui interroge directement le système d&#39;exploitation :</p><table tabindex="0"><thead><tr><th>Plateforme</th><th>Méthode de détection</th></tr></thead><tbody><tr><td><strong>Windows</strong></td><td>Commandes PowerShell</td></tr><tr><td><strong>Linux</strong></td><td>Système de fichiers <code>/proc</code> + <code>lspci</code></td></tr><tr><td><strong>macOS</strong></td><td>Commandes <code>sysctl</code></td></tr></tbody></table><h3 id="informations-affichees" tabindex="-1">Informations affichées <a class="header-anchor" href="#informations-affichees" aria-label="Permalink to &quot;Informations affichées&quot;">​</a></h3><ul><li><strong>CPU</strong> -- Nom du modèle, nombre de cœurs, architecture</li><li><strong>RAM</strong> -- Mémoire totale installée avec utilisation en direct</li><li><strong>GPU</strong> -- Nom du modèle, VRAM, version du pilote</li><li><strong>Stockage</strong> -- Capacité du disque et espace disponible</li></ul><div class="tip custom-block"><p class="custom-block-title">Première configuration</p><p>Les informations matérielles sont lues au démarrage du serveur de développement Vite. Si la page Système affiche &quot;Redémarrer le serveur de développement&quot;, arrêtez et relancez <code>npm run dev</code>.</p></div><h2 id="statut-d-ollama" tabindex="-1">Statut d&#39;Ollama <a class="header-anchor" href="#statut-d-ollama" aria-label="Permalink to &quot;Statut d&#39;Ollama&quot;">​</a></h2><p>La section Ollama affiche :</p><ul><li><strong>Statut de connexion</strong> -- Si Ollama est accessible</li><li><strong>Modèles en cours d&#39;exécution</strong> -- Quels modèles sont actuellement chargés en mémoire</li><li><strong>Allocation mémoire</strong> -- Quantité de RAM/VRAM utilisée par chaque modèle chargé</li><li><strong>Paramètres d&#39;inférence</strong> -- Paramètres par défaut de l&#39;instance en cours d&#39;exécution</li></ul><h2 id="utilisation-du-stockage" tabindex="-1">Utilisation du stockage <a class="header-anchor" href="#utilisation-du-stockage" aria-label="Permalink to &quot;Utilisation du stockage&quot;">​</a></h2><p>Une visualisation du stockage IndexedDB utilisé par LLMxRay :</p><ul><li>Stockage total utilisé par l&#39;origine</li><li>Répartition par base de données (conversations, benchmarks, vecteurs RAG, données d&#39;entraînement)</li><li>Barre de pourcentage visuelle</li></ul><h2 id="astuces" tabindex="-1">Astuces <a class="header-anchor" href="#astuces" aria-label="Permalink to &quot;Astuces&quot;">​</a></h2><ul><li><strong>Utilisation élevée de la RAM ?</strong> -- Ollama conserve les modèles en mémoire après la première utilisation. Utilisez des modèles quantifiés plus légers (Q4) ou réduisez la longueur de contexte dans les Paramètres.</li><li><strong>GPU non détecté ?</strong> -- Assurez-vous que vos pilotes GPU sont à jour. Sous Linux, vérifiez que <code>lspci</code> est disponible.</li><li>La visualisation du stockage se rafraîchit automatiquement lorsque vous accédez à cette page.</li></ul>',18)])])}const f=a(r,[["render",n]]);export{h as __pageData,f as default};
